import { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import { API, setAuthToken } from '../App';
import { Button } from '../components/ui/button';
import { Input } from '../components/ui/input';
import { Label } from '../components/ui/label';
import { toast } from 'sonner';
import { useNavigate } from 'react-router-dom';
import { Building2, Upload, X } from 'lucide-react';

const BusinessSetupPage = () => {
  const navigate = useNavigate(); const fileInputRef = useRef(null);
  const [loading, setLoading] = useState(false); const [uploading, setUploading] = useState(false);
  const [logoPreview, setLogoPreview] = useState(''); const [currencies, setCurrencies] = useState([]); const [themes, setThemes] = useState([]);
  const [formData, setFormData] = useState({ restaurant_name: '', address: '', phone: '', email: '', gstin: '', fssai: '', currency: 'INR', tax_rate: 5.0, receipt_theme: 'classic', logo_url: '', website: '', tagline: '', footer_message: 'Thank you for dining with us!' });
  useEffect(() => { axios.get(`${API}/currencies`).then(r => setCurrencies(r.data)).catch(() => {}); axios.get(`${API}/receipt-themes`).then(r => setThemes(r.data)).catch(() => {}); }, []);
  const update = (key, value) => setFormData(prev => ({ ...prev, [key]: value }));
  const handleLogoUpload = async (e) => { const file = e.target.files[0]; if (!file) return; if (!file.type.startsWith('image/')) return toast.error('Please select an image file'); setUploading(true); try { const upload = new FormData(); upload.append('file', file); const response = await axios.post(`${API}/upload/image`, upload, { headers: { 'Content-Type': 'multipart/form-data' } }); update('logo_url', response.data.image_url); setLogoPreview(response.data.image_url); toast.success('Logo uploaded successfully!'); } catch { toast.error('Failed to upload logo'); } finally { setUploading(false); } };
  const handleSubmit = async (e) => { e.preventDefault(); if (!formData.restaurant_name || !formData.phone) return toast.error('Please fill required fields'); setLoading(true); try { const response = await axios.post(`${API}/business/setup`, formData); const storedUser = JSON.parse(localStorage.getItem('user') || '{}'); const updatedUser = { ...storedUser, setup_completed: true, business_settings: response.data.settings || formData }; const token = localStorage.getItem('token'); if (token) setAuthToken(token, updatedUser); else localStorage.setItem('user', JSON.stringify(updatedUser)); toast.success('Business setup complete!'); navigate('/dashboard', { replace: true }); } catch (error) { toast.error(error.response?.data?.detail || 'Failed to complete setup'); } finally { setLoading(false); } };
  const fields = [['email','Email *','restaurant@example.com'],['gstin','GSTIN (Optional)','22AAAAA0000A1Z5'],['fssai','FSSAI License (Optional)','12345678901234'],['website','Website (Optional)','www.yourrestaurant.com'],['tagline','Tagline (Optional)','Delicious food, memorable moments']];
  return <div className="business-setup-page">
    <aside className="business-setup-sidebar"><div className="setup-brand-mark"><Building2 size={28} /></div><h2>Let&apos;s Set Up<br />Your Restaurant</h2><p>Tell us about your business and we&apos;ll personalize your experience.</p><div className="setup-benefits"><div className="setup-benefit"><span className="benefit-icon benefit-purple"><Building2 size={19} /></span><div><strong>Personalized Setup</strong><small>Get recommendations based on your business type</small></div></div><div className="setup-benefit"><span className="benefit-icon benefit-green">↗</span><div><strong>Smart Features</strong><small>Enable features that matter most for your business</small></div></div><div className="setup-benefit"><span className="benefit-icon benefit-blue">◇</span><div><strong>Secure &amp; Reliable</strong><small>Your data is secure and backed up</small></div></div></div><div className="setup-storefront" aria-hidden="true"><div className="storefront-sign">RESTAURANT</div><div className="storefront-awning" /><div className="storefront-window" /></div></aside>
    <main className="business-setup-main"><div className="setup-header"><div><h1>Setup Your Business</h1><p>Let&apos;s configure your restaurant details to get started</p></div><button type="button" className="setup-help"><span>?</span><div><strong>Need Help?</strong><small>We&apos;re here to assist you</small></div></button></div><div className="setup-progress" aria-label="Setup progress">{['Business Info','Location','Other Details','Preferences'].map((step, i) => <div className={`setup-step ${i === 0 ? 'active' : ''}`} key={step}><span>{i + 1}</span><strong>{step}</strong></div>)}</div>
      <form onSubmit={handleSubmit} className="setup-form"><section className="setup-section"><div className="setup-section-title"><Building2 size={18} /><h2>Business Information</h2></div><div className="setup-fields setup-fields-top"><div className="logo-upload-field"><Label>Logo (Optional)</Label><button type="button" className="logo-dropzone" onClick={() => fileInputRef.current?.click()} disabled={uploading}><Upload size={18} /><strong>{uploading ? 'Uploading...' : 'Upload Logo'}</strong><small>PNG, JPG up to 2MB</small></button><input ref={fileInputRef} type="file" accept="image/*" onChange={handleLogoUpload} hidden />{logoPreview && <div className="logo-preview"><img src={logoPreview} alt="Restaurant logo preview" /><button type="button" onClick={() => { setLogoPreview(''); update('logo_url',''); }} aria-label="Remove logo"><X size={13} /></button></div>}</div><div><Label>Restaurant Name <em>*</em></Label><Input value={formData.restaurant_name} onChange={e => update('restaurant_name',e.target.value)} placeholder="e.g., Delicious Bites" required data-testid="restaurant-name-input" /></div><div><Label>Phone Number <em>*</em></Label><Input value={formData.phone} onChange={e => update('phone',e.target.value)} placeholder="+91 1234567890" required data-testid="phone-input" /></div></div><div className="setup-fields"><div className="field-wide"><Label>Address <em>*</em></Label><Input value={formData.address} onChange={e => update('address',e.target.value)} placeholder="Street, City, State, PIN" data-testid="address-input" /></div>{fields.map(([key,label,placeholder]) => <div key={key}><Label>{label}</Label><Input type={key === 'email' ? 'email' : 'text'} value={formData[key]} onChange={e => update(key,e.target.value)} placeholder={placeholder} /></div>)}<div className="field-full"><Label>Receipt Footer Message</Label><Input value={formData.footer_message} onChange={e => update('footer_message',e.target.value)} placeholder="Thank you for dining with us!" /></div></div></section><section className="setup-section"><div className="setup-section-title"><span className="section-glyph">₹</span><h2>Tax &amp; Currency</h2></div><div className="setup-fields"><div><Label>Currency <em>*</em></Label><select className="setup-select" value={formData.currency} onChange={e => update('currency',e.target.value)} data-testid="currency-select">{currencies.map(c => <option key={c.code} value={c.code}>{c.symbol} {c.code} - {c.name || 'Indian Rupee'}</option>)}</select></div><div><Label>Tax Rate (%) <em>*</em></Label><Input type="number" step="0.01" value={formData.tax_rate} onChange={e => update('tax_rate',parseFloat(e.target.value))} placeholder="5" /></div></div></section><section className="setup-section"><div className="setup-section-title"><Building2 size={18} /><h2>Receipt Theme</h2></div><div className="theme-grid">{themes.map(theme => <button key={theme.id} type="button" onClick={() => update('receipt_theme',theme.id)} className={`theme-card ${formData.receipt_theme === theme.id ? 'selected' : ''}`} data-testid={`theme-${theme.id}`}><span className="theme-icon">{theme.id === 'classic' ? '▤' : theme.id === 'modern' ? '✦' : theme.id === 'minimal' ? '—' : theme.id === 'elegant' ? '♛' : theme.id === 'compact' ? '▣' : '☷'}</span><span><strong>{theme.name}</strong><small>{theme.description}</small></span>{formData.receipt_theme === theme.id && <b className="theme-check">✓</b>}</button>)}</div></section><div className="setup-actions"><Button type="button" variant="outline" onClick={() => navigate(-1)}><X size={16} /> Cancel Setup</Button><div><Button type="submit" disabled={loading} className="setup-submit" data-testid="complete-setup-button">{loading ? 'Setting up...' : 'Save & Continue'} <span>→</span></Button><small>You can change these details later</small></div></div></form></main></div>;
};
export default BusinessSetupPage;
