const readManaged = () => {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null') || starterPosts; } catch { return starterPosts; }
};
const writeManaged = (posts) => localStorage.setItem(STORAGE_KEY, JSON.stringify(posts));
export const getManagedPosts = () => (typeof window === 'undefined' ? starterPosts : readManaged());
export const getAllBlogPosts = () => [...blogPosts, ...getManagedPosts().filter(post => !blogPosts.some(seed => seed.slug === post.slug))];
export const getPublishedBlogPosts = () => getAllBlogPosts().filter(post => post.status !== 'draft' && (!post.scheduledDate || new Date(post.scheduledDate) <= new Date()));
export const saveManagedPost = (post) => { const posts = getManagedPosts(); const next = { ...post, id: post.id || `studio-${Date.now()}`, lastModified: new Date().toISOString().slice(0, 10) }; writeManaged([...posts.filter(item => item.id !== next.id), next]); return next; };
export const deleteManagedPost = (id) => writeManaged(getManagedPosts().filter(post => post.id !== id));
export const resetManagedPosts = () => writeManaged(starterPosts);
export { starterPosts };
